head.b:skin:
:root { --primary: #06b6d4; --primary-bright: #67e8f9; --primary-dim: rgba(6, 182, 212, 0.3); --dark: #0f172a; --panel: #1e293b; --text-main: #f1f5f9; --text-muted: #94a3b8; --green: #10B981; --red: #EF4444; --saffron: #ff9933; --border-color: rgba(255,255,255,0.1); }
* { box-sizing: border-box; outline: none; -webkit-user-select: none; user-select: none; } 
input, textarea { -webkit-user-select: text; user-select: text; }
html, body { margin: 0; padding: 0; background: var(--dark); color: var(--text-main); font-family: 'Segoe UI', sans-serif; width: 100vw; height: 100vh; overflow: hidden !important; position: fixed; top: 0; left: 0; }
::-webkit-scrollbar { width: 5px; } ::-webkit-scrollbar-thumb { background: var(--primary); }
.cyber-bg { position: fixed; top: 0; left: 0; width: 100%; height: 100%; z-index: -1; background: radial-gradient(circle at 50% 0%, #1e293b 0%, var(--dark) 80%); }
.grid-anim { position: absolute; width: 200%; height: 200%; top: -50%; left: -50%; background-image: linear-gradient(rgba(6, 182, 212, 0.03) 1px, transparent 1px), linear-gradient(90deg, rgba(6, 182, 212, 0.03) 1px, transparent 1px); background-size: 40px 40px; transform: perspective(500px) rotateX(60deg); opacity: 0.4; }

#toast-container { position: fixed; bottom: 20px; right: 20px; z-index: 100002; display: flex; flex-direction: column; gap: 10px; pointer-events: none; }
.toast-box { background: rgba(15, 23, 42, 0.95); border-left: 4px solid var(--primary); color: #fff; padding: 15px 20px; border-radius: 4px; box-shadow: 0 5px 15px rgba(0,0,0,0.5); display: flex; align-items: center; gap: 12px; font-size: 13px; font-weight: 600; backdrop-filter: blur(10px); animation: slideIn 0.3s ease-out forwards; pointer-events: auto; min-width: 280px; border-top: 1px solid rgba(255,255,255,0.1); }
.toast-box.success { border-color: var(--green); } .toast-box.error { border-color: var(--red); }
@keyframes slideIn { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }

#main-view { width: 100%; height: 100%; display: flex; flex-direction: column; transition: 0.3s; }

#bio-view, #photo-view { 
    position: fixed; top: 0; left: 0; width: 100%; height: 100%; 
    background: #e0e0e0; z-index: 20000; 
    display: none; flex-direction: column; overflow: hidden;
    font-family: 'Segoe UI', sans-serif; color: #333;
}
#bio-view.active, #photo-view.active { display: flex; }

/* LOGIN STYLES (User Provided) */
#login-screen { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(15, 23, 42, 0.98); z-index: 99999; display: flex; justify-content: center; align-items: center; backdrop-filter: blur(15px); padding: 20px; font-family: 'Segoe UI', sans-serif; }
.login-box { width: 100%; max-width: 360px; background: rgba(30, 41, 59, 0.95); border: 2px solid #06b6d4; padding: 35px 25px; border-radius: 20px; text-align: center; box-shadow: 0 0 60px rgba(6, 182, 212, 0.25); display: flex; flex-direction: column; align-items: center; }
.login-profile-wrapper { width: 100px; height: 100px; margin: 0 auto 15px auto; position: relative; flex-shrink: 0; }
.login-pic { width: 100%; height: 100%; border-radius: 50%; border: 3px solid #06b6d4; object-fit: cover; box-shadow: 0 0 20px rgba(6, 182, 212, 0.3); }
.login-title-text { font-size: 20px; font-weight: 800; color: #fff; margin: 0; letter-spacing: 1px; text-transform: uppercase; }
.login-subtitle { font-size: 11px; color: #06b6d4; font-weight: 700; margin-top: 5px; letter-spacing: 2px; text-transform: uppercase; margin-bottom: 25px; }
.login-form-area { width: 100%; border-top: 1px solid rgba(255,255,255,0.1); padding-top: 20px; }
.login-field { text-align: center; font-size: 14px; letter-spacing: 2px; font-weight: bold; background: rgba(0,0,0,0.4); border: 1px solid rgba(255,255,255,0.1); color: #fff; padding: 14px; margin-bottom: 15px; border-radius: 10px; width: 100%; transition: 0.3s; }
.login-field:focus { border-color: #06b6d4; box-shadow: 0 0 15px rgba(6, 182, 212, 0.3); outline: none; }
.login-submit-btn { width: 100%; background: linear-gradient(135deg, #06b6d4, #0891b2); color: #000; padding: 14px; font-weight: 800; border-radius: 10px; border: none; cursor: pointer; transition: 0.3s; margin-top: 5px; letter-spacing: 1px; }
.login-submit-btn:hover { transform: translateY(-2px); box-shadow: 0 5px 20px rgba(6, 182, 212, 0.3); }
.login-msg { height: 20px; font-size: 11px; font-weight: 700; letter-spacing: 1px; margin-top: 15px; color: #94a3b8; }

/* SWITCH TOGGLE STYLES */
.switch input:checked + .slider { background-color: var(--primary); }
.switch input:focus + .slider { box-shadow: 0 0 1px var(--primary); }
.slider.round:before { position: absolute; content: ""; height: 14px; width: 14px; left: 3px; bottom: 3px; background-color: white; transition: .4s; border-radius: 50%; }
.switch input:checked + .slider:before { transform: translateX(20px); }

/* PHOTO STUDIO LAYOUT */
#photo-view { background: #0b1120; color: #e2e8f0; }
.photo-studio-container { display: flex; flex-direction: column; height: 100%; padding: 0; }
.ps-layout { display: flex; flex: 1; overflow: hidden; }
.ps-upload-zone { width: 320px; background: #111827; border-right: 1px solid #334155; padding: 20px; display: flex; flex-direction: column; gap: 15px; overflow-y: auto; }
.ps-box-title { color: #94a3b8; font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 5px; }
.ps-input { width: 100%; background: #1f2937; border: 1px solid #374151; color: #fff; padding: 12px; border-radius: 8px; font-size: 14px; font-weight: 600; text-align: center; transition: 0.3s; }
.ps-input:focus { border-color: var(--primary); box-shadow: 0 0 15px var(--primary-dim); }
.upload-drop-area { border: 2px dashed #374151; border-radius: 12px; padding: 30px 10px; text-align: center; cursor: pointer; transition: 0.3s; background: rgba(255,255,255,0.02); }
.upload-drop-area:hover { border-color: var(--primary); background: rgba(6, 182, 212, 0.05); }
.preview-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; max-height: 150px; overflow-y: auto; }
.mini-preview { width: 100%; height: 60px; object-fit: cover; border-radius: 4px; border: 1px solid #4b5563; }
.btn-action { width: 100%; padding: 12px; border: none; border-radius: 8px; font-weight: 800; cursor: pointer; color: #fff; transition: 0.2s; display: flex; justify-content: center; align-items: center; gap: 8px; font-size: 13px; }
.btn-upload { background: linear-gradient(135deg, var(--green), #059669); box-shadow: 0 4px 15px rgba(16, 185, 129, 0.3); }
.btn-upload:hover { transform: translateY(-2px); }
.ps-gallery-zone { flex: 1; padding: 25px; display: flex; flex-direction: column; overflow: hidden; background: radial-gradient(circle at 50% 50%, #1e293b 0%, #0f172a 100%); }
.search-bar { display: flex; gap: 10px; margin-bottom: 20px; max-width: 600px; margin: 0 auto 20px auto; width: 100%; }
.btn-search { background: var(--primary); color: #000; width: auto; padding: 0 25px; }
.main-viewer { flex: 1; background: #020617; border-radius: 16px; border: 1px solid #334155; display: flex; justify-content: center; align-items: center; overflow: hidden; position: relative; box-shadow: 0 10px 30px rgba(0,0,0,0.5); min-height: 200px; }
.main-viewer img { max-width: 100%; max-height: 100%; object-fit: contain; }
.empty-state { text-align: center; color: #64748b; font-size: 14px; font-weight: 600; }
.thumb-strip { height: 100px; margin-top: 20px; display: flex; gap: 12px; overflow-x: auto; padding: 5px; scroll-behavior: smooth; }
.thumb-item { height: 80px; width: 70px; border-radius: 8px; cursor: pointer; border: 2px solid transparent; opacity: 0.6; transition: 0.2s; object-fit: cover; background: #000; }
.thumb-item:hover { opacity: 1; transform: translateY(-3px); }
.thumb-item.active { border-color: var(--primary); opacity: 1; box-shadow: 0 0 15px var(--primary-dim); }
.gallery-controls { display: flex; gap: 15px; margin-top: 15px; justify-content: center; }
.ctrl-btn { padding: 10px 20px; border-radius: 6px; border: none; font-weight: bold; cursor: pointer; color: #fff; font-size: 12px; }
.btn-dl { background: #f59e0b; }
.btn-del { background: #ef4444; }

@media screen and (max-width: 768px) {
    .ps-layout { flex-direction: column; overflow-y: auto; }
    .ps-upload-zone { width: 100%; height: auto; flex-shrink: 0; border-right: none; border-bottom: 1px solid #334155; }
    .ps-gallery-zone { height: auto; min-height: 500px; }
}

.bio-toolbar { background: #2c3e50; color: #fff; padding: 10px 20px; display: flex; justify-content: space-between; align-items: center; box-shadow: 0 2px 5px rgba(0,0,0,0.2); }
.bio-btn { background: #3498db; color: white; border: none; padding: 8px 15px; border-radius: 4px; cursor: pointer; font-weight: bold; margin-left: 10px; }
.bio-btn.save { background: #27ae60; }
.bio-btn.back { background: #e74c3c; }
.bio-container { display: flex; flex: 1; overflow: hidden; }
.input-panel { width: 350px; background: #fff; padding: 15px; overflow-y: auto; border-right: 1px solid #ccc; }
.preview-panel { flex: 1; background: #525659; padding: 20px; overflow-y: auto; display: flex; justify-content: center; align-items: flex-start; }
.a4-page { width: 210mm; height: 296mm; background: white; padding: 30px 35px; box-shadow: 0 0 15px rgba(0,0,0,0.5); position: relative; color: #000; line-height: 1.25; font-family: 'Times New Roman', serif; display: flex; flex-direction: column; transform-origin: top center; }
.cv-content-wrapper { flex: 1; display: flex; flex-direction: column; }
.cv-footer-wrapper { margin-top: auto; padding-top: 10px; }

/* FIXED PHOTO & HEADER LAYOUT */
.cv-header-wrapper { position: relative; min-height: 180px; width: 100%; }
.cv-photo-box { position: absolute; top: 0; right: 0; width: 35mm; height: 45mm; border: 2px solid #002d72; display: flex; justify-content: center; align-items: center; overflow: hidden; background: #f0f0f0; }
.cv-main-content { margin-right: 38mm; display: flex; flex-wrap: wrap; gap: 20px; padding-bottom: 10px; border-bottom: 1px solid #ddd; margin-bottom: 10px; align-items: flex-start; }
.cv-identity { flex: 1 1 200px; min-width: 200px; }
.cv-address-block { flex: 2 1 320px; min-width: 320px; display: flex; gap: 15px; font-size: 11pt; }

.split-container { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 5px; }
.split-left { flex: 1; }
.split-right { flex: 0 0 45%; margin-left: 15px; padding-left: 15px; border-left: 2px solid #002d72; }
h3 { margin-bottom: 5px; font-size: 1.1em; }
.bio-group { background: #f8f9fa; padding: 8px; border-left: 3px solid #3498db; margin: 10px 0 5px; font-weight: bold; font-size: 13px; }
.bio-inp { width: 100%; padding: 6px; margin-bottom: 5px; border: 1px solid #ccc; border-radius: 4px; font-size: 13px; }
.bio-row { display: flex; gap: 5px; } .bio-col { flex: 1; }
.hidden { display: none !important; }
.lang-row { display: flex; align-items: center; gap: 5px; margin-bottom: 5px; font-size: 13px; }
.lang-chk { width: auto !important; margin-right: 5px; }
.lang-sel { flex: 1; padding: 4px; border:1px solid #ccc; border-radius:4px; }
.dob-group { display: flex; gap: 5px; align-items: center; }
.dob-box { flex: 1; text-align: center; padding: 6px; border: 1px solid #ccc; border-radius: 4px; font-weight: bold; font-size: 13px; }
.dob-box:focus { border-color: var(--primary); outline: none; }
.fit-content-wrapper { width: 100%; display: flex; align-items: center; background: #fff; border: 1px solid #ccc; border-radius: 4px; overflow: hidden; margin-bottom:5px; }
.auto-resize-text { border: none !important; width: 100%; padding: 8px; font-size: 13px; font-weight: bold; background:transparent; color: #000 !important; }

/* NEW STATS MONITOR STYLE */
.storage-monitor { background: var(--panel); border: 1px solid var(--primary-dim); border-radius: 12px; padding: 20px; box-shadow: 0 0 15px rgba(0,0,0,0.3); transition: 0.3s; margin-bottom: 25px; }
.storage-monitor:hover { box-shadow: 0 0 25px var(--primary-dim); border-color: var(--primary); transform: translateY(-3px); }
.sm-title { font-size: 12px; color: var(--text-muted); font-weight: 800; letter-spacing: 1px; margin-bottom: 15px; display: flex; align-items: center; gap: 8px; }
.sm-grid { display: flex; gap: 15px; }
.sm-box { flex: 1; background: rgba(0,0,0,0.3); border-radius: 10px; padding: 15px; text-align: center; border: 1px solid rgba(255,255,255,0.05); transition: 0.3s; position: relative; overflow: hidden; }
.sm-box::before { content: ''; position: absolute; top: 0; left: 0; width: 100%; height: 2px; background: linear-gradient(90deg, transparent, currentColor, transparent); opacity: 0.5; }
.bio-stat { color: var(--green); }
.photo-stat { color: var(--saffron); }
.sm-icon { font-size: 20px; margin-bottom: 5px; opacity: 0.8; }
.sm-count { font-size: 24px; font-weight: 900; color: #fff; text-shadow: 0 0 10px currentColor; }
.sm-label { font-size: 9px; font-weight: 700; color: var(--text-muted); letter-spacing: 0.5px; }

@page { size: A4; margin: 0; }
@media print {
    body * { visibility: hidden; }
    #bio-view, .a4-page, .a4-page * { visibility: visible; }
    .bio-toolbar, .input-panel { display: none !important; }
    .preview-panel { background: white; padding: 0; display: block; overflow: visible; }
    .a4-page { box-shadow: none; margin: 0 auto; width: 100%; height: 100vh; position: absolute; top: 0; left: 0; print-color-adjust: exact; -webkit-print-color-adjust: exact; }
}
#welcome-flash { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: #000; z-index: 100000; display: none; justify-content: center; align-items: center; flex-direction: column; transition: opacity 0.5s ease; }
.flash-text { font-size: 40px; font-weight: 900; color: var(--saffron); text-transform: uppercase; text-shadow: 0 0 30px var(--saffron); animation: zoomText 0.5s ease-out forwards; text-align: center; letter-spacing: 2px; }
@keyframes zoomText { 0% { transform: scale(0.5); opacity: 0; } 100% { transform: scale(1); opacity: 1; } }
.laser-h { position: absolute; background: var(--primary); z-index: 50; opacity: 0.8; box-shadow: 0 0 15px var(--primary-bright); height: 2px; width: 100%; left: 0; background: linear-gradient(90deg, transparent, var(--primary-bright), var(--primary), transparent); animation: scanH 4s infinite linear; }
@keyframes scanH { 0% { transform: translateX(-100%); } 100% { transform: translateX(100%); } }
.header { background: var(--panel); backdrop-filter: blur(10px); padding: 0 20px; display: flex; justify-content: space-between; align-items: center; height: 75px; width: 100%; flex-shrink: 0; position: relative; overflow: hidden; border: none; }
.header .laser-h { bottom: 0; }
footer { background: var(--panel) !important; padding: 0 25px; height: 35px; width: 100%; display: flex; align-items: center; position: absolute; bottom: 0; left: 0; overflow: hidden; color: var(--text-muted) !important; font-size: 11px; font-weight: 600; border: none; z-index: 100; }
footer .laser-h { top: 0; animation-delay: 2s; }
.clock-hud { display: flex; flex-direction: column; align-items: center; background: #000; border: 2px solid var(--primary); padding: 2px 30px; min-width: 200px; clip-path: polygon(10% 0, 90% 0, 100% 50%, 90% 100%, 10% 100%, 0% 50%); position: absolute; left: 50%; transform: translateX(-50%); z-index: 10; box-shadow: 0 0 15px rgba(0,0,0,0.8); }
.clock-hud::after { content: ''; position: absolute; top: 0; left: 0; width: 5px; height: 100%; background: var(--primary); animation: scanClock 4s infinite linear; opacity: 0.8; box-shadow: 0 0 10px var(--primary); }
@keyframes scanClock { 0% {left:0;} 50% {left:98%;} 100% {left:0;} }
#clock-display { font-family: 'Courier New', monospace; font-size: 28px; color: var(--primary-bright); font-weight: 900; text-shadow: 0 0 5px var(--primary-soft); letter-spacing: 1px; line-height: 1.1; }
#date-display { color: #fff; font-size: 11px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase; }
.status-badge { display: flex; align-items: center; gap: 8px; background: rgba(0,0,0,0.2); border: none; box-shadow: 0 0 10px rgba(0,0,0,0.2); padding: 6px 14px; border-radius: 20px; font-size: 11px; font-weight: bold; margin-left: auto; margin-right: 20px; }
.led { width: 8px; height: 8px; border-radius: 50%; transition: 0.3s; }
.online-mode { color: var(--green); } .online-mode .led { background: var(--green); box-shadow: 0 0 8px var(--green); }
.offline-mode { color: var(--red); } .offline-mode .led { background: var(--red); animation: blink 0.5s infinite; }
.header-btns { display: flex; gap: 10px; }
.head-btn { background: rgba(255, 255, 255, 0.08); border: none; color: #fff; padding: 8px 16px; cursor: pointer; font-weight: 700; border-radius: 6px; transition: 0.2s; font-size: 11px; letter-spacing: 0.5px; }
.head-btn:hover { background: var(--primary); color: #000; box-shadow: 0 0 15px var(--primary-soft); }
.content { display: flex; height: calc(100vh - 110px); overflow: hidden; width: 100%; }
.dashboard { flex: 1; padding: 0 25px 25px 25px; position: relative; overflow-y: scroll; }
.sidebar-left { width: 280px; background: rgba(30, 41, 59, 0.5); padding: 20px; display: flex; flex-direction: column; gap: 15px; position: relative; border: none; flex-shrink: 0; overflow-y: scroll; }
.sidebar-right { width: 300px; background: rgba(30, 41, 59, 0.5); padding: 20px; display: flex; flex-direction: column; gap: 15px; position: relative; border: none; flex-shrink: 0; overflow-y: scroll;}
.cat-section { margin-bottom: 25px; }
.cat-header { display: flex; align-items: center; gap: 10px; background: linear-gradient(to right, var(--primary-dim), transparent); border-left: 3px solid var(--primary); padding: 8px 15px; margin: 15px 0 15px 0; font-size: 12px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase; color: var(--text-main); }
.cat-header i { color: var(--primary); }
.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 15px; padding-bottom: 20px; }
.card { position: relative; background: #0f172a; padding: 1px; border-radius: 8px; overflow: hidden; z-index: 1; height: 140px; transition: 0.3s; animation: popIn 0.5s forwards; border: none; }
.card::before { content: ''; position: absolute; top: -50%; left: -50%; width: 200%; height: 200%; background: conic-gradient(transparent, transparent, transparent, var(--primary-dim)); animation: rotateMagic 6s linear infinite; z-index: -2; opacity: 0.4; filter: blur(8px); }
.card:hover::before { background: conic-gradient(transparent, transparent, transparent, var(--primary)); opacity: 0.8; filter: blur(5px); animation-duration: 3s; }
.card-inner-content { background: rgba(17, 24, 39, 0.98); border-radius: 7px; padding: 15px; height: 100%; position: relative; z-index: -1; display: flex; flex-direction: column; justify-content: space-between; }
.card:hover { transform: translateY(-3px); }
@keyframes rotateMagic { 0% {transform: rotate(0deg);} 100% {transform: rotate(360deg);} }
@keyframes popIn { from { transform: translateY(10px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
.card-head { display: flex; align-items: center; gap: 10px; margin-bottom: 5px; }
.card-icon { width: 32px; height: 32px; font-size: 12px; background: var(--primary-dim); border-radius: 6px; flex-shrink: 0; display: flex; justify-content: center; align-items: center; color: var(--primary-bright); }
.card h3 { color: var(--text-main); font-weight: 700; margin: 0; font-size: 12px; letter-spacing: 0.5px; white-space: normal; line-height: 1.3; overflow: hidden; text-overflow: ellipsis; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.actions { display: flex; justify-content: space-between; gap: 10px; margin-top: 10px; width: 100%; border-top: 1px solid rgba(255,255,255,0.05); padding-top: 12px; }
.btn-act { display: flex; justify-content: center; align-items: center; height: 34px; padding: 0 12px; border-radius: 6px; border: none; cursor: pointer; font-size: 11px; font-weight: 800; transition: all 0.3s ease; }
.btn-open { background: linear-gradient(135deg, var(--primary), #0891b2); color: #000 !important; flex: 1; text-transform: uppercase; letter-spacing: 1px; box-shadow: 0 4px 10px rgba(6, 182, 212, 0.2); }
.btn-open:hover { background: linear-gradient(135deg, var(--primary-bright), var(--primary)); box-shadow: 0 6px 15px rgba(6, 182, 212, 0.4); transform: translateY(-2px); }
.btn-edit { display: none !important; width: 34px; background: rgba(255, 153, 51, 0.15); color: var(--saffron); }
body.edit-mode-active .btn-edit { display: flex !important; }
.btn-edit:hover { background: rgba(255, 153, 51, 0.3); color: #fff; box-shadow: 0 0 10px rgba(255, 153, 51, 0.3); }
.owner-card { position: relative; background: #020617; padding: 1px; border-radius: 12px; text-align: center; overflow: hidden; z-index: 1; box-shadow: 0 5px 15px -5px rgba(0,0,0,0.5); }
.owner-card::before { content: ''; position: absolute; top: -50%; left: -50%; width: 200%; height: 200%; background: conic-gradient(transparent, transparent, transparent, var(--primary)); animation: rotateMagic 4s linear infinite; z-index: -2; opacity: 0.5; filter: blur(5px);}
.owner-inner { background: #0f172a; border-radius: 11px; padding: 20px 15px; height: 100%; position: relative; z-index: -1; }
.profile-container { position: relative; display: inline-block; margin-bottom: 10px; }
.profile-pic { width: 70px; height: 70px; border-radius: 50%; border: 2px solid var(--primary); object-fit: cover; object-position: top; box-shadow: 0 0 15px var(--primary-soft); }
.owner-name { font-size: 16px; font-weight: 800; color: #fff; margin: 0; letter-spacing: 0.5px; display: flex; justify-content: center; align-items: center; gap: 5px; }
.owner-role { font-size: 10px; color: var(--primary); font-weight: 700; margin-top: 2px; letter-spacing: 1px; text-transform: uppercase; margin-bottom: 5px; }
.tagline { font-size: 11px; color: #94a3b8; margin-bottom: 15px; line-height: 1.4; font-style: italic; opacity: 0.8; }
.stats-grid { display: flex; justify-content: space-between; background: rgba(255,255,255,0.03); border-radius: 8px; padding: 10px; margin-bottom: 15px; }
.stat-box { text-align: center; flex: 1; border-right: 1px solid rgba(255,255,255,0.05); }
.stat-box:last-child { border: none; }
.stat-val { font-size: 13px; font-weight: 800; color: #fff; }
.stat-lbl { font-size: 8px; color: var(--text-muted); text-transform: uppercase; margin-top: 2px; letter-spacing:0.5px; }
.owner-details { border-top: 1px solid rgba(255,255,255,0.05); padding-top: 15px; text-align: left; display: flex; flex-direction: column; gap: 8px; }
.detail-item { display: flex; align-items: center; gap: 10px; font-size: 11px; color: var(--text-main); padding: 5px 8px; border-radius: 6px; transition: 0.3s; background: rgba(255,255,255,0.02); }
.detail-item:hover { background: rgba(6, 182, 212, 0.1); }
.detail-icon { width: 22px; height: 22px; background: rgba(6, 182, 212, 0.1); border-radius: 6px; display: flex; justify-content: center; align-items: center; color: var(--primary); font-size: 10px; }
.gm-panel, .day-hud, .net-monitor, .hack-term { border: 1px solid rgba(6, 182, 212, 0.3); box-shadow: 0 0 8px rgba(0, 0, 0, 0.3); border-radius: 8px; transition: 0.3s; }
.gm-panel:hover, .day-hud:hover, .net-monitor:hover, .hack-term:hover { box-shadow: 0 0 20px var(--primary-dim); border-color: var(--primary-bright); transform: translateY(-3px); }
input, textarea, select { width: 100%; padding: 12px 15px; background: var(--dark); border: 1px solid var(--border-color); color: var(--text-main); margin-bottom: 12px; border-radius: 6px; font-family: 'Segoe UI', sans-serif; transition:0.3s; font-size: 13px; }
input:focus, textarea:focus, select:focus { border-color: var(--primary); outline: none; box-shadow: 0 0 10px var(--primary-dim); outline: none; }
.gm-panel { background: var(--panel); overflow: hidden; }
.gm-header { background: var(--dark); padding: 12px 20px; display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid var(--border-color); }
.gm-title { font-weight: 700; color: var(--gmail); display: flex; align-items: center; gap: 8px; }
.gm-inbox-btn { background: rgba(255,255,255,0.05); color: var(--text-main); border: none; padding: 6px 14px; border-radius: 6px; font-size: 11px; cursor: pointer; transition:0.3s; }
.gm-inbox-btn:hover { background: rgba(234, 67, 53, 0.2); color: var(--gmail); }
.gm-body { padding: 20px; }
.gm-send { width: 100%; background: var(--gmail); border: none; color: white; padding: 12px; font-weight: bold; border-radius: 6px; cursor: pointer; transition: 0.3s; }
.gm-send:hover { box-shadow: 0 0 15px rgba(234, 67, 53, 0.5); }
.day-hud { background: var(--panel); padding: 20px; text-align: center; }
.orb { width: 12px; height: 12px; background: var(--primary-bright); border-radius: 50%; margin: 0 auto 10px; box-shadow: 0 0 15px var(--primary); animation: pulse 2s infinite alternate; }
@keyframes pulse { to { transform: scale(1.4); opacity: 0.8; } }
.net-monitor { background: var(--panel); padding: 20px; }
.bars { display: flex; gap: 3px; height: 24px; align-items: flex-end; margin-top: 10px; }
.bar { flex: 1; background: var(--green); opacity: 0.2; } .bar.active { opacity: 1; box-shadow: 0 0 5px var(--green); }
.hack-term { margin-top: 25px; background: #000; overflow: hidden; }
.hack-head { background: #111; padding: 10px 15px; border-bottom: 1px solid #333; display: flex; justify-content: space-between; align-items: center; }
.hack-title { font-family: monospace; font-size: 11px; color: var(--primary); font-weight: bold; }
.hack-body { height: 150px; padding: 15px; font-family: monospace; font-size: 11px; color: var(--primary); overflow: hidden; background: #000; position:relative; }
.log-line { margin-bottom: 4px; }
.scan-line { position: absolute; top: 0; left: 0; width: 100%; height: 5px; background: var(--primary-dim); animation: scan 4s linear infinite; }
#search { position: sticky; top: 0; z-index: 100; margin-top: 25px; border: 1px solid var(--primary); box-shadow: 0 0 10px var(--primary-dim); background: rgba(15, 23, 42, 0.95); }
#sys-menu { display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.8); backdrop-filter: blur(5px); z-index: 10000; justify-content: center; align-items: center; }
.sys-content { background: var(--panel); padding: 35px; border: 2px solid var(--primary); text-align: center; width: 320px; border-radius: 16px; box-shadow: 0 0 30px var(--primary-dim); }
.sys-content button { border: none !important; }
@media screen and (max-width: 768px) {
    .content { flex-direction: column; overflow-y: auto; height: calc(100vh - 95px); -webkit-overflow-scrolling: touch; }
    .sidebar-left, .sidebar-right, .dashboard { width: 100%; height: auto; border: none; padding: 15px; flex-shrink: 0; padding-bottom: 30px; }
    .clock-hud { display: none; }
    .header { padding: 0 15px; height: 60px; }
    .header div:nth-child(2) { font-size: 18px !important; }
    .header span { display: none; }
    .sidebar-left .laser-v, .sidebar-right .laser-v { display: none; }
    .flash-text { font-size: 28px; }
}

body.script:
//
