        {"name":"CSC LOGIN","url":"https://connect.csc.gov.in/","cat":"Tools & Utility"},
        {"name":"NDC FLIGHT","url":"https://ndc.deals/","cat":"Tools & Utility"},
        {"name":"YOUTUBE","url":"https://WWW.YOUTUBE.COM","cat":"Tools & Utility"}
    ];

    let localData = [...PRELOADED];
    let globalData = [];
    let editingKey = null;

    // --- NEW FIREBASE LOGIN LOGIC ---
    function attemptLogin() {
        let pass = document.getElementById('login-pass').value;
        let stat = document.getElementById('login-status');
        const adminEmail = "nirobdas03@gmail.com"; // Your Admin Email

        if(pass) {
            stat.innerText = 'AUTHENTICATING...';
            stat.style.color = '#ff9933';

            // Using Firebase Auth instead of simple check
            firebase.auth().signInWithEmailAndPassword(adminEmail, pass)
            .then((userCredential) => {
                stat.innerText = 'ACCESS GRANTED';
                stat.style.color = '#10B981';

                setTimeout(() => {
                    document.getElementById('login-screen').style.display = 'none';
                    document.getElementById('welcome-flash').style.display = 'none';
                    initCloudData();
                    startHacking(); 
                    updateDay();
                    updateStats(); 
                }, 1000);
            })
            .catch((error) => {
                stat.innerText = 'ACCESS DENIED'; 
                stat.style.color = '#EF4444';
                console.error(error);
            });
        }
    }
    document.getElementById('login-pass').addEventListener('keypress', function (e) { if (e.key === 'Enter') attemptLogin(); });

    function forgotPass() {
        const adminEmail = "nirobdas03@gmail.com";
        if(firebase.auth()) {
            firebase.auth().sendPasswordResetEmail(adminEmail)
            .then(() => { alert("Password reset link sent to: " + adminEmail + "\nCheck your inbox!"); })
            .catch((error) => { alert("Error: " + error.message); });
        }
    }

    // --- LOGOUT UPDATED ---
    function logout() {
        firebase.auth().signOut().then(() => {
            document.getElementById('main-view').style.display = 'none';
            document.getElementById('login-screen').style.display = 'flex';
            document.getElementById('login-pass').value = ''; 
            document.getElementById('login-status').innerText = 'WAITING...';
            document.getElementById('login-status').style.color = '#94a3b8';
            closeSys(); 
        });
    }

    // --- MASTER SETTINGS SYSTEM ---
    let sysConfig = { bio: true, photo: true };

    function openMasterSettings() {
        closeSys();
        document.getElementById('master-settings-view').style.display = 'flex';

        db.ref('system_settings').once('value').then(snap => {
            let d = snap.val();
            if(d) {
                sysConfig = d;
                document.getElementById('toggle-bio').checked = d.bio;
                document.getElementById('toggle-photo').checked = d.photo;
            } else {
                document.getElementById('toggle-bio').checked = true;
                document.getElementById('toggle-photo').checked = true;
            }
        });
    }

    function closeMasterSettings() {
        document.getElementById('master-settings-view').style.display = 'none';
    }

    function saveMasterSettings() {
        let bioStatus = document.getElementById('toggle-bio').checked;
        let photoStatus = document.getElementById('toggle-photo').checked;

        db.ref('system_settings').set({
            bio: bioStatus,
            photo: photoStatus
        }).then(() => {
            sysConfig = { bio: bioStatus, photo: photoStatus };
            showToast("Settings Updated Successfully!", "success");
            closeMasterSettings();
        }).catch(e => showToast("Error Saving Settings", "error"));
    }

    function loadSystemConfig() {
        db.ref('system_settings').on('value', snap => {
            let d = snap.val();
            if(d) sysConfig = d;
        });
    }

    // --- DYNAMIC EXTENSION SYSTEM ---
    function saveCustomExtension() {
        let title = document.getElementById('cust-title').value;
        let code = document.getElementById('cust-code').value;

        if(!title || !code) { showToast("Please enter Title and Code!", "error"); return; }

        db.ref('custom_extension').set({ title: title, code: code, active: true }).then(() => {
            showToast("New Section Added Successfully!", "success");
            loadCustomExtensionBtn();
            closeMasterSettings();
        });
    }

    function loadCustomExtensionBtn() {
        db.ref('custom_extension').once('value').then(snap => {
            let d = snap.val();
            let btn = document.getElementById('btn-custom-feature');
            if(d && d.active) {
                btn.style.display = 'block';
                document.getElementById('menu-cust-title').innerText = d.title;
            } else {
                btn.style.display = 'none';
            }
        });
    }

    function openCustomView() {
        closeSys();
        showToast("Loading Module...", "success");

        db.ref('custom_extension').once('value').then(snap => {
            let d = snap.val();
            if(d && d.code) {
                let container = document.getElementById('custom-content-area');
                document.getElementById('custom-view-title').innerText = d.title;
                document.getElementById('custom-view').style.display = 'flex';
                container.innerHTML = d.code;
                let scripts = container.getElementsByTagName("script");
                for(let i=0; i<scripts.length; i++) {
                    let newScript = document.createElement("script");
                    newScript.text = scripts[i].text;
                    document.body.appendChild(newScript);
                }
            }
        });
    }

    function closeCustomView() {
        document.getElementById('custom-view').style.display = 'none';
    }

    // --- DYNAMIC LOGIN SYSTEM (Visual Only) ---
    function saveLoginDesign() {
        let code = document.getElementById('custom-login-code').value;
        // Removed ID check because logic is hardcoded now
        db.ref('login_design').set(code).then(() => {
            showToast("Login HTML Updated!", "success");
            document.querySelector('.login-box').innerHTML = code;
            closeMasterSettings();
        });
    }

    function resetLoginDesign() {
        if(confirm("Reset to default login design?")) {
            db.ref('login_design').remove().then(() => {
                showToast("Reset Successful! Reloading...", "success");
                setTimeout(() => location.reload(), 1000);
            });
        }
    }

    function loadDynamicLogin() {
        if(db) {
            // AUTO FIX: Wipes problematic design on load to ensure functionality
            // Remove the line below if you want to enable custom HTML for login again
            db.ref('login_design').remove(); 

            db.ref('login_design').once('value').then(snap => {
                let design = snap.val();
                if(design && design.length > 20) {
                    document.querySelector('.login-box').innerHTML = design;
                }
            });
        }
    }

    function initCloudData() {
        loadSystemConfig(); 
        loadCustomExtensionBtn();
        if(!linksRef) { render(localData); return; }
        linksRef.on('value', (snapshot) => {
            const data = snapshot.val();
            if(data) { globalData = Object.keys(data).map(key => ({ ...data[key], key: key })); } 
            else { globalData = []; }
            render([...localData, ...globalData]);
        });
    }

    function updateStats() {
        db.ref('biodata').on('value', (snap) => {
            const count = snap.numChildren();
            animateValue("count-bio", 0, count, 1000);
        });
        db.ref('photovault').on('value', (snap) => {
            let totalPhotos = 0;
            snap.forEach((childSnap) => { totalPhotos += childSnap.numChildren(); });
            animateValue("count-photo", 0, totalPhotos, 1000);
        });
    }

    function animateValue(id, start, end, duration) {
        let obj = document.getElementById(id);
        let range = end - start;
        let minTimer = 50;
        let stepTime = Math.abs(Math.floor(duration / range));
        stepTime = Math.max(stepTime, minTimer);
        let startTime = new Date().getTime();
        let endTime = startTime + duration;
        let timer;
        function run() {
            let now = new Date().getTime();
            let remaining = Math.max((endTime - now) / duration, 0);
            let value = Math.round(end - (remaining * range));
            obj.innerHTML = value;
            if (value == end) { clearInterval(timer); }
        }
        timer = setInterval(run, stepTime);
        run();
    }

    function render(data) {
        const grid = document.getElementById('grid');
        const categories = {};
        data.forEach((item, index) => {
            let cat = item.cat || "Tools & Utility";
            if(!categories[cat]) categories[cat] = [];
            categories[cat].push({...item, idx: index}); 
        });
        let html = '';
        for (let cat in categories) {
            html += `<div class="cat-section"><div class="cat-header"><i class="fa-solid fa-layer-group"></i> ${cat}</div><div class="grid">${categories[cat].map(item => `<div class="card item"><div class="card-inner-content"><div class="card-head"><div class="card-icon"><i class="fa-solid fa-link"></i></div><h3 style="margin:0; font-size:12px; line-height:1.2; height:32px; overflow:hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;">${item.name}</h3></div><div class="actions"><button class="btn-act btn-edit" onclick="editAnyLink('${item.key || 'local_' + item.idx}', '${item.name}', '${item.url}', '${item.cat}')"><i class="fa-solid fa-pen"></i></button><a href="${item.url}" target="_blank" class="btn-act btn-open">OPEN</a></div></div></div>`).join('')}</div></div>`;
        }
        grid.innerHTML = html;
    }

    function saveLinkToCloud() {
        if(!linksRef) { showToast("Firebase Error", "error"); return; }
        let c = document.getElementById('b-cat').value, n = document.getElementById('b-name').value, u = document.getElementById('b-url').value;
        if(!n || !u) { showToast("Enter Name/URL", "error"); return; }

        if(editingKey) {
            linksRef.child(editingKey).update({ name: n, url: u, cat: c }).then(() => { resetForm(); showToast("Updated!", "success"); });
        } else {
            linksRef.push({ name: n, url: u, cat: c }).then(() => { resetForm(); showToast("Saved!", "success"); });
        }
    }

    function editAnyLink(k, n, u, c) {
        document.getElementById('b-cat').value = c; document.getElementById('b-name').value = n; document.getElementById('b-url').value = u;
        editingKey = k.startsWith('local_') ? null : k;
        document.getElementById('add-btn').innerText = editingKey ? "UPDATE" : "SAVE NEW";
        document.querySelector('.sidebar-left').scrollTop = 0;
    }
    function resetForm() { document.getElementById('b-name').value = ""; document.getElementById('b-url').value = ""; editingKey = null; document.getElementById('add-btn').innerText = "SAVE TO CLOUD"; }
    function toggleEditMode() { document.body.classList.toggle('edit-mode-active'); closeSys(); }
    function showToast(msg, type) { const c = document.getElementById('toast-container'); const b = document.createElement('div'); b.className = `toast-box ${type}`; b.innerHTML = `<i class="fa-solid ${type==='success'?'fa-check':'fa-exclamation'}"></i> ${msg}`; c.appendChild(b); setTimeout(() => b.remove(), 3000); }
    function openSys() { document.getElementById('sys-menu').style.display = 'flex'; }
    function closeSys() { document.getElementById('sys-menu').style.display = 'none'; }
    function filter() { let v = document.getElementById('search').value.toLowerCase(); let cards = document.getElementsByClassName('item'); for(let c of cards) { c.style.display = c.innerText.toLowerCase().includes(v) ? "" : "none"; } }
    function initBars() { document.getElementById('net-bars').innerHTML = Array(20).fill('<div class="bar"></div>').join(''); }
    function updateDay() { document.getElementById('bengali-day').innerText = ['রবিবার','সোমবার','মঙ্গলবার','বুধবার','বৃহস্পতিবার','শুক্রবার','শনিবার'][new Date().getDay()]; }
    setInterval(() => { const n = new Date(); document.getElementById('clock-display').innerText = n.toLocaleTimeString(); document.getElementById('date-display').innerText = n.toLocaleDateString(); updateDay(); }, 1000);
    function startHacking() { setInterval(() => { const c = document.getElementById('hack-console'); if(c) { let d = document.createElement('div'); d.className = 'log-line'; d.innerText = '> System Active...'; c.appendChild(d); c.scrollTop = c.scrollHeight; } }, 2000); }

    window.sendWA = function() {
        let phone = document.getElementById('wa-phone').value.trim();
        let msg = document.getElementById('wa-msg').value.trim();
        if(!phone) { alert("Please enter mobile number"); return; }
        if(phone.length === 10) phone = "91" + phone;
        window.open("https://wa.me/" + phone + "?text=" + encodeURIComponent(msg), '_blank');
    };

    window.toggleFull = function() {
        var elem = document.documentElement;
        if (!document.fullscreenElement && !document.mozFullScreenElement && !document.webkitFullscreenElement && !document.msFullscreenElement) {
            if (elem.requestFullscreen) { elem.requestFullscreen(); }
            else if (elem.msRequestFullscreen) { elem.msRequestFullscreen(); }
            else if (elem.mozRequestFullScreen) { elem.mozRequestFullScreen(); }
            else if (elem.webkitRequestFullscreen) { elem.webkitRequestFullscreen(Element.ALLOW_KEYBOARD_INPUT); }
        } else {
            if (document.exitFullscreen) { document.exitFullscreen(); }
            else if (document.msExitFullscreen) { document.msExitFullscreen(); }
            else if (document.mozCancelFullScreen) { document.mozCancelFullScreen(); }
            else if (document.webkitExitFullscreen) { document.webkitExitFullscreen(); }
        }
    };

    // --- UPDATED OPEN FUNCTIONS WITH LOCK ---
    function openBioData() { 
        if(!sysConfig.bio) { showToast("ACCESS DENIED: Bio Data Locked by Admin.", "error"); return; }
        document.getElementById('main-view').style.display='none'; 
        document.getElementById('bio-view').classList.add('active'); 
        closeSys(); 
    }
    function closeBioData() { document.getElementById('bio-view').classList.remove('active'); document.getElementById('main-view').style.display='flex'; }

    function resetBioForm() {
         document.querySelectorAll('.bio-inp').forEach(el => {
            if(el.type === 'checkbox') el.checked = false;
            else el.value = '';
         });
         document.getElementById('nation').value = 'Indian';
         document.getElementById('state').value = 'West Bengal';
         document.getElementById('ai_qual').value = '10th';
         document.getElementById('ai_exp').value = 'Fresh';
         document.getElementById('gender').value = 'Male';
         document.getElementById('cv-photo').src = '';
         document.getElementById('cv-photo').style.display = 'none';
         document.getElementById('dob_d').value = '';
         document.getElementById('dob_m').value = '';
         document.getElementById('dob_y').value = '';
         upd(); 
         showToast("Form Reset for New Customer!", "success");
    }

    function loadPhoto(event) {
        const file = event.target.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = function(e) {
                const img = new Image();
                img.onload = function() {
                    const canvas = document.createElement('canvas');
                    const ctx = canvas.getContext('2d');
                    const MAX_WIDTH = 300;
                    const MAX_HEIGHT = 400;
                    let width = img.width;
                    let height = img.height;
                    if (width > height) { if (width > MAX_WIDTH) { height *= MAX_WIDTH / width; width = MAX_WIDTH; } } 
                    else { if (height > MAX_HEIGHT) { width *= MAX_HEIGHT / height; height = MAX_HEIGHT; } }
                    canvas.width = width; canvas.height = height;
                    ctx.drawImage(img, 0, 0, width, height);
                    const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
                    document.getElementById('cv-photo').src = dataUrl;
                    document.getElementById('cv-photo').style.display = 'block';
                }
                img.src = e.target.result;
            }
            reader.readAsDataURL(file);
        }
    }

    function saveBioData() {
        let m = document.getElementById('cust-mobile').value;
        if(!m) { showToast("Enter Customer Mobile Number", "error"); return; }
        showToast("Saving to Cloud...", "success");
        let data = {};
        document.querySelectorAll('.bio-inp, .lang-chk, .lang-sel').forEach(el => {
            if(el.id) { data[el.id] = el.type === 'checkbox' ? el.checked : el.value; }
        });
        data['dob'] = document.getElementById('dob_d').value + "/" + document.getElementById('dob_m').value + "/" + document.getElementById('dob_y').value;

        let photoSrc = document.getElementById('cv-photo').src;
        if(photoSrc && photoSrc.startsWith('data:image')) { data['photoData'] = photoSrc; }
        db.ref('biodata/' + m).set(data)
        .then(() => { 
            showToast("Bio-Data Saved Successfully!", "success");
        })
        .catch((error) => { showToast("Error: " + error.message, "error"); });
    }

    function loadBioData() {
        let m = document.getElementById('cust-mobile').value;
        if(!m) { showToast("Enter Mobile Number to Load", "error"); return; }
        showToast("Searching Online Database...", "success");
        db.ref('biodata/' + m).once('value')
        .then((snapshot) => {
            let data = snapshot.val();
            if(data) {
                for(let k in data) { 
                    let el = document.getElementById(k);
                    if(el) {
                        if(el.type === 'checkbox') el.checked = data[k];
                        else el.value = data[k];
                    }
                }
                if(data['dob']) {
                    let parts = data['dob'].split('/');
                    if(parts.length === 3) {
                        document.getElementById('dob_d').value = parts[0];
                        document.getElementById('dob_m').value = parts[1];
                        document.getElementById('dob_y').value = parts[2];
                        handleDob();
                    }
                }
                if(data['photoData']) {
                    let photoEl = document.getElementById('cv-photo');
                    photoEl.src = data['photoData'];
                    photoEl.style.display = 'block';
                } else {
                    document.getElementById('cv-photo').style.display = 'none';
                }
                upd(); 
                showToast("Data Loaded from Cloud!", "success");
            } else { showToast("No data found.", "error"); }
        })
        .catch((error) => { showToast("Network Error!", "error"); });
    }

    function smartPrint() {
        let page = document.getElementById('cv-page-content');
        page.style.fontSize = ''; 
        const MAX_HEIGHT = 1115; 
        let fontSizePercent = 100;
        while (page.scrollHeight > page.clientHeight && fontSizePercent > 60) {
            fontSizePercent -= 1;
            page.style.fontSize = (fontSizePercent / 100) + 'em';
        }
        window.print();
    }

    function handlePin(p) {
        if(p.length===6){
            fetch('https://api.postalpincode.in/pincode/'+p).then(r=>r.json()).then(d=>{
                if(d[0].Status==='Success'){
                    let i = d[0].PostOffice[0];
                    document.getElementById('dist').value=i.District; document.getElementById('state').value=i.State;
                    let s=document.getElementById('po'); s.innerHTML='<option value="">Select PO</option>'; 
                    d[0].PostOffice.forEach(o=>{let x=document.createElement('option');x.text=o.Name;s.add(x)});
                    let psInput = document.getElementById('ps');
                    let psList = document.getElementById('ps_list');
                    psList.innerHTML = '';
                    let uniqueBlocks = [...new Set(d[0].PostOffice.map(item => item.Block))];
                    uniqueBlocks.forEach(block => {
                        if(block !== "NA") { let opt = document.createElement('option'); opt.value = block; psList.appendChild(opt); }
                    });
                    if(uniqueBlocks.length === 1 && uniqueBlocks[0] !== "NA") { psInput.value = uniqueBlocks[0]; } else { psInput.value = ""; }
                    sync();
                }
            });
        }
        upd();
    }

    function sync() { 
        if(document.getElementById('same').checked) { 
            let map = { 'pres_rel_type': 'perm_rel_type', 'pres_rel_name': 'perm_rel_name', 'vill': 'p_vill', 'po': 'p_po', 'ps': 'p_ps', 'dist': 'p_dist', 'state': 'p_state', 'pin': 'p_pin' };
            for(let src in map) { document.getElementById(map[src]).value = document.getElementById(src).value; }
        } 
        upd(); 
    }

    function genObj() { document.getElementById('cv-obj').innerText = document.getElementById('ai_exp').value==='Exp' ? "Experienced professional seeking a challenging position to leverage my skills." : "I aspire to work in a challenging and dynamic organization where I can utilize my skills."; }

    function adjustFontSize(element) {
        let defaultSize = 13; 
        element.style.fontSize = defaultSize + "px"; 
        let parentWidth = element.parentElement.clientWidth;
        while (element.scrollWidth > parentWidth && defaultSize > 8) {
            defaultSize -= 0.5;
            element.style.fontSize = defaultSize + "px";
        }
    }

    function handleDob(el) {
        let d = document.getElementById('dob_d').value;
        let m = document.getElementById('dob_m').value;
        let y = document.getElementById('dob_y').value;

        if(d && m && y) {
            let fullDate = d + "/" + m + "/" + y;
            document.getElementById('cv-dob').innerText = fullDate;
            document.getElementById('r-dob').classList.remove('hidden');
        } else {
            document.getElementById('r-dob').classList.add('hidden');
        }

        if(el && el.value.length === el.maxLength) {
            let next = el.nextElementSibling?.nextElementSibling; 
            if(next && next.tagName === 'INPUT') next.focus();
        }
    }

    function setText(inputId, outputId, rowId) { 
        let v = document.getElementById(inputId).value; 
        let el = document.getElementById(outputId);
        if(el) el.innerText = v;
        if(rowId) {
            let row = document.getElementById(rowId);
            if(row) { if(v && v.trim() !== "") row.classList.remove('hidden'); else row.classList.add('hidden'); }
        }
    }

