    function openPhotoStudio() { 
        if(!sysConfig.photo) { showToast("ACCESS DENIED: Photo Studio Locked by Admin.", "error"); return; }
        document.getElementById('main-view').style.display='none'; 
        document.getElementById('photo-view').classList.add('active'); 
        closeSys(); 
    }
    function closePhotoStudio() { document.getElementById('photo-view').classList.remove('active'); document.getElementById('main-view').style.display='flex'; }

    let imagesToUpload = [];

    function previewUploads(event) {
        const files = event.target.files;
        const grid = document.getElementById('preview-grid');
        grid.innerHTML = '';
        imagesToUpload = [];

        if (files.length > 0) {
            document.querySelector('.upload-drop-area').style.display = 'none';
            Array.from(files).forEach(file => {
                const reader = new FileReader();
                reader.onload = function(e) {
                    const img = new Image();
                    img.onload = function() {
                        const canvas = document.createElement('canvas');
                        const ctx = canvas.getContext('2d');
                        const MAX_WIDTH = 800; const MAX_HEIGHT = 1000;
                        let width = img.width; let height = img.height;
                        if (width > height) { if (width > MAX_WIDTH) { height *= MAX_WIDTH / width; width = MAX_WIDTH; } } 
                        else { if (height > MAX_HEIGHT) { width *= MAX_HEIGHT / height; height = MAX_HEIGHT; } }
                        canvas.width = width; canvas.height = height;
                        ctx.drawImage(img, 0, 0, width, height);
                        const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
                        imagesToUpload.push(dataUrl);
                        const thumb = document.createElement('img');
                        thumb.src = dataUrl;
                        thumb.className = 'mini-preview';
                        grid.appendChild(thumb);
                    }
                    img.src = e.target.result;
                }
                reader.readAsDataURL(file);
            });
        }
    }

    function uploadPhotos() {
        let m = document.getElementById('ps-up-mobile').value;
        if(!m) { showToast("Enter Customer Number in Upload Zone", "error"); return; }
        if(imagesToUpload.length === 0) { showToast("Select photos first", "error"); return; }
        showToast("Uploading " + imagesToUpload.length + " photos...", "success");
        let completed = 0;
        imagesToUpload.forEach(imgData => {
            db.ref('photovault/' + m).push({ photo: imgData, date: new Date().toLocaleDateString() })
            .then(() => {
                completed++;
                if(completed === imagesToUpload.length) {
                    showToast("All Photos Uploaded!", "success");
                    setTimeout(() => {
                        document.getElementById('ps-up-mobile').value = '';
                        document.getElementById('ps-file-input').value = '';
                        document.getElementById('preview-grid').innerHTML = '';
                        document.querySelector('.upload-drop-area').style.display = 'block';
                        imagesToUpload = [];
                    }, 1500);
                }
            });
        });
    }

    let currentViewKey = null;

    function loadGallery() {
        let m = document.getElementById('ps-search-mobile').value;
        if(!m) { showToast("Enter Mobile Number", "error"); return; }
        showToast("Searching...", "success");
        db.ref('photovault/' + m).once('value').then((snap) => {
            const strip = document.getElementById('thumb-strip');
            strip.innerHTML = '';
            if(snap.exists()) {
                const data = snap.val();
                let images = [];
                if(data.photo && typeof data.photo === 'string') { images.push({ key: 'legacy', ...data }); } 
                else { Object.keys(data).forEach(key => { images.push({ key: key, ...data[key] }); }); }

                if(images.length > 0) {
                    let lastImg = images[images.length - 1];
                    setMainImage(lastImg.photo, lastImg.key);
                    for(let i = images.length - 1; i >= 0; i--) {
                        let item = images[i];
                        const thumb = document.createElement('img');
                        thumb.className = 'thumb-item';
                        thumb.src = item.photo;
                        thumb.onclick = function() {
                            setMainImage(item.photo, item.key);
                            document.querySelectorAll('.thumb-item').forEach(t => t.classList.remove('active'));
                            this.classList.add('active');
                        };
                        strip.appendChild(thumb);
                    }
                    showToast("Found " + images.length + " Photos", "success");
                }
            } else {
                resetGallery();
                showToast("No Photos Found", "error");
            }
        });
    }

    function setMainImage(src, key) {
        document.getElementById('main-img').src = src;
        document.getElementById('main-img').style.display = 'block';
        document.getElementById('main-placeholder').style.display = 'none';
        currentViewKey = key;
    }

    function resetGallery() {
        document.getElementById('main-img').style.display = 'none';
        document.getElementById('main-placeholder').style.display = 'block';
        document.getElementById('thumb-strip').innerHTML = '';
        currentViewKey = null;
    }

    function downloadCurrent() {
        let src = document.getElementById('main-img').src;
        if(!src || !src.startsWith('data:image')) { showToast("No photo to download", "error"); return; }
        let a = document.createElement('a');
        a.href = src;
        a.download = 'studio_' + Date.now() + '.jpg';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
    }

    function deleteCurrent() {
        let m = document.getElementById('ps-search-mobile').value;
        if(!m || !currentViewKey) { showToast("Select a photo first", "error"); return; }
        let pass = prompt("Enter Password to Delete:");
        if(pass === "1234") {
            if(currentViewKey === 'legacy') {
                db.ref('photovault/' + m).remove().then(() => { showToast("Deleted!", "success"); loadGallery(); });
            } else {
                db.ref('photovault/' + m + '/' + currentViewKey).remove().then(() => { showToast("Deleted!", "success"); loadGallery(); });
            }
        } else { alert("Incorrect Password"); }
    }

    // LOAD LOGIN DESIGN ON STARTUP
    loadDynamicLogin();

    // --- SECURITY SYSTEM (ANTI-HACK) ---
    document.addEventListener('contextmenu', event => event.preventDefault());
    document.onkeydown = function(e) {
        if(e.keyCode == 123) return false; // F12
        if(e.ctrlKey && e.shiftKey && e.keyCode == 'I'.charCodeAt(0)) return false; // Ctrl+Shift+I
        if(e.ctrlKey && e.shiftKey && e.keyCode == 'C'.charCodeAt(0)) return false; // Ctrl+Shift+C
        if(e.ctrlKey && e.shiftKey && e.keyCode == 'J'.charCodeAt(0)) return false; // Ctrl+Shift+J
        if(e.ctrlKey && e.keyCode == 'U'.charCodeAt(0)) return false; // Ctrl+U
    }

